// Original SVG pixel portraits. All lobby data stays in this browser tab.
const avatarList=[
 {id:'cat',name:'Cool Cat',color:'#ffcb65',ears:'cat',glasses:true},
 {id:'rabbit',name:'Disco Bunny',color:'#f9e9f6',ears:'rabbit',glasses:true},
 {id:'frog',name:'Funky Frog',color:'#81ce45',ears:'frog'},
 {id:'fox',name:'Professor Fox',color:'#f5a454',ears:'cat',spectacles:true},
 {id:'bear',name:'Boogie Bear',color:'#bb8cde',ears:'bear'},
 {id:'robot',name:'Rhythm Bot',color:'#73d9e9',ears:'robot'},
 {id:'panda',name:'Party Panda',color:'#f3f1ed',ears:'bear',patches:true},
 {id:'duck',name:'DJ Duck',color:'#ffe471',ears:'duck'}
];
function portrait(id){const a=avatarList.find(a=>a.id===id)||avatarList[0];let top='';if(a.ears==='cat')top=`<path d="M10 22V4h12l10 14h8L50 4h12v26" fill="${a.color}"/><path d="M14 18V9h6l7 10zm32 0 8-9h4v10" fill="#ec86a6"/>`;if(a.ears==='rabbit')top='<path d="M14 28V4h12v24h20V4h12v28" fill="#f9e9f6"/><path d="M18 8h4v16h-4zm32 0h4v16h-4z" fill="#ed8bc4"/>';if(a.ears==='bear')top=`<path d="M7 25V12h16v13zm42 0V12h16v13z" fill="${a.patches?'#252135':a.color}"/>`;if(a.ears==='robot')top='<path d="M34 4h4v14h-4z" fill="#73d9e9"/><path d="M30 2h12v8H30z" fill="#ff2ea6"/>';if(a.ears==='frog')top='<path d="M10 28V12h20v16zm32 0V12h20v16z" fill="#81ce45"/><path d="M14 14h12v14H14zm32 0h12v14H46z" fill="#fff8d7"/><path d="M18 16h6v8h-6zm30 0h6v8h-6z" fill="#181225"/>';let face=`<path d="M14 22h44v6h6v28h-6v8H14v-8H8V28h6z" fill="${a.color}"/>`;if(a.ears==='frog')face='<path d="M10 26h52v6h6v22h-6v8H10v-8H4V32h6z" fill="#81ce45"/>';let details=a.ears==='frog'?'<path d="M15 42h42v5H15zm6 5h30v5H21z" fill="#304c27"/><path d="M21 47h30v5H21z" fill="#ff9c91"/>':a.ears==='robot'?'<path d="M16 29h40v17H16z" fill="#201831"/><path d="M22 33h8v8h-8zm20 0h8v8h-8z" fill="#b6ff00"/><path d="M26 52h20v5H26z" fill="#201831"/>':'<path d="M21 33h6v8h-6zm24 0h6v8h-6z" fill="#251b31"/><path d="M33 44h6v5h-6zm-6 9h18v4H27z" fill="#593950"/>';if(a.ears==='cat')details='<path d="M18 43h36v13h-6v6H24v-6h-6z" fill="#fff4dc"/>'+details;if(a.patches)details='<path d="M15 29h16v17H15zm26 0h16v17H41z" fill="#252135"/><path d="M22 33h5v7h-5zm23 0h5v7h-5z" fill="#fff"/><path d="M32 49h8v5h-8zm-5 8h18v4H27z" fill="#252135"/>';if(a.glasses)details+='<path d="M12 30h48v5h-4v12H40V35h-8v12H16V35h-4z" fill="#1b1727"/><path d="M20 34h8v3h-8zm24 0h8v3h-8z" fill="#ffffffb0"/>';if(a.spectacles)details+='<path d="M15 29h17v18H15zm25 0h17v18H40z" fill="none" stroke="#251b31" stroke-width="3"/><path d="M32 35h8" stroke="#251b31" stroke-width="3"/>';if(a.ears==='duck')details+='<path d="M28 43h26v12H28z" fill="#f89832"/>';return `<svg viewBox="0 0 72 72" aria-hidden="true" shape-rendering="crispEdges">${top}${face}${details}</svg>`}
const crewColors=['#b6ff00','#ff2ea6','#00f0ff','#bd79ff'];
let nextPlayerId=3;
const players=[{id:1,name:'',avatar:'cat'},{id:2,name:'',avatar:'rabbit'}];
const lobby=document.querySelector('.lobby-screen'),homeScreen=document.querySelector('.title-screen'),playerGrid=document.querySelector('#player-grid'),avatarDialog=document.querySelector('#avatar-dialog');
let editingPlayer=null;
function openLobby(){homeScreen.hidden=true;lobby.hidden=false;document.querySelector('.arcade').classList.add('in-lobby');renderPlayers();document.querySelector('#lobby-title').focus();window.scrollTo(0,0)}
function goHome(){lobby.hidden=true;homeScreen.hidden=false;document.querySelector('.arcade').classList.remove('in-lobby');document.querySelector('[data-mode="Team"]').focus()}
function nameError(){if(players.length<2)return 'Add at least 2 players.';const names=players.map(p=>p.name.trim().toLocaleLowerCase());if(names.some(n=>!n))return 'Enter a name for each player.';if(new Set(names).size!==names.length)return 'Use a different name for each player.';return ''}
function updateLobby(){const error=nameError();document.querySelector('#player-count').textContent=`PLAYERS (${players.length} / 4)`;document.querySelector('#start-team').disabled=!!error;document.querySelector('#lobby-status').textContent=error||'';}
function renderPlayers(){playerGrid.replaceChildren();for(let i=0;i<4;i++){const p=players[i];const card=document.createElement(p?'article':'button');card.className=p?'player-card':'empty-player';card.style.setProperty('--player-color',crewColors[i]);if(!p){card.type='button';card.setAttribute('aria-label',`Add player ${players.length+1}`);card.innerHTML='<span class="add-symbol" aria-hidden="true">+</span><span>ADD PLAYER</span>';card.addEventListener('click',()=>{if(players.length>=4)return;const added={id:nextPlayerId++,name:'',avatar:avatarList[players.length].id};players.push(added);renderPlayers();playerGrid.querySelector(`[data-player-id="${added.id}"] input`).focus();blip(440)});playerGrid.appendChild(card);continue}card.dataset.playerId=p.id;card.setAttribute('aria-label',`Player ${i+1}`);card.innerHTML=`<div class="card-top"><span>${'PLAYER '+(i+1)}</span><button class="remove-player" aria-label="Remove player ${i+1}">×</button></div><button class="avatar-button" aria-label="Choose avatar for player ${i+1}">${portrait(p.avatar)}<span>CHANGE AVATAR</span></button><label class="sr-only" for="player-${p.id}">P${i+1}</label><input id="player-${p.id}" class="player-name" maxlength="16" placeholder="YOUR NAME" autocomplete="off" spellcheck="false" aria-label="Player ${i+1} name">`;const input=card.querySelector('input');input.value=p.name;input.addEventListener('input',()=>{p.name=input.value;updateLobby()});card.querySelector('.remove-player').addEventListener('click',()=>{players.splice(players.findIndex(x=>x.id===p.id),1);renderPlayers();(playerGrid.querySelector('.empty-player')||document.querySelector('#home')).focus()});card.querySelector('.avatar-button').addEventListener('click',()=>openAvatarPicker(p.id));playerGrid.appendChild(card)}updateLobby()}
function openAvatarPicker(id){editingPlayer=id;const p=players.find(p=>p.id===id);if(!p)return;document.querySelector('#avatar-title').textContent=`Player ${players.indexOf(p)+1} avatar`;const grid=document.querySelector('#avatar-options');grid.replaceChildren();for(const avatar of avatarList){const b=document.createElement('button');b.className='avatar-option';b.setAttribute('aria-label',avatar.name);b.setAttribute('aria-pressed',String(avatar.id===p.avatar));b.innerHTML=portrait(avatar.id)+`<span>${avatar.name}</span>`;b.addEventListener('click',()=>{p.avatar=avatar.id;avatarDialog.close();renderPlayers();playerGrid.querySelector(`[data-player-id="${p.id}"] .avatar-button`).focus();blip(440)});grid.appendChild(b)}avatarDialog.showModal()}
document.querySelector('.close-picker').addEventListener('click',()=>avatarDialog.close());avatarDialog.addEventListener('click',e=>{if(e.target===avatarDialog)avatarDialog.close()});document.querySelector('#home').addEventListener('click',goHome);

document.querySelector('#start-team').addEventListener('click',()=>{if(nameError())return;startTeamPreview()});
dialog.addEventListener('close',()=>{document.querySelector('#back').textContent='BACK TO MENU';document.querySelector('.preview-note').innerHTML="Gameplay is not connected yet."});



